CREATE TABLE solborne_presales_outbox (registration_id TEXT PRIMARY KEY REFERENCES solborne_registrations(id),sequence INTEGER NOT NULL DEFAULT 1,synced_sequence INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,last_attempt_at INTEGER,synced_at INTEGER);
INSERT INTO solborne_presales_outbox(registration_id) SELECT id FROM solborne_registrations;
CREATE TRIGGER solborne_presales_registration_insert AFTER INSERT ON solborne_registrations BEGIN INSERT INTO solborne_presales_outbox(registration_id) VALUES(NEW.id); END;
CREATE TRIGGER presales_solborne_ai_walks_insert AFTER INSERT ON solborne_ai_walks BEGIN UPDATE solborne_presales_outbox SET sequence=sequence+1 WHERE registration_id=NEW.registration_id; END;
CREATE TRIGGER presales_solborne_ai_walks_update AFTER UPDATE ON solborne_ai_walks BEGIN UPDATE solborne_presales_outbox SET sequence=sequence+1 WHERE registration_id=NEW.registration_id; END;
CREATE TRIGGER presales_solborne_ai_walks_delete AFTER DELETE ON solborne_ai_walks BEGIN UPDATE solborne_presales_outbox SET sequence=sequence+1 WHERE registration_id=OLD.registration_id; END;
CREATE TRIGGER presales_solborne_walk_completions_insert AFTER INSERT ON solborne_walk_completions BEGIN UPDATE solborne_presales_outbox SET sequence=sequence+1 WHERE registration_id=NEW.registration_id; END;
CREATE TRIGGER presales_solborne_walk_completions_update AFTER UPDATE ON solborne_walk_completions BEGIN UPDATE solborne_presales_outbox SET sequence=sequence+1 WHERE registration_id=NEW.registration_id; END;
CREATE TRIGGER presales_solborne_walk_completions_delete AFTER DELETE ON solborne_walk_completions BEGIN UPDATE solborne_presales_outbox SET sequence=sequence+1 WHERE registration_id=OLD.registration_id; END;
CREATE TRIGGER presales_solborne_owner_reviews_insert AFTER INSERT ON solborne_owner_reviews BEGIN UPDATE solborne_presales_outbox SET sequence=sequence+1 WHERE registration_id=(SELECT registration_id FROM solborne_walk_completions WHERE id=NEW.completion_id); END;
CREATE TRIGGER presales_solborne_owner_reviews_update AFTER UPDATE ON solborne_owner_reviews BEGIN UPDATE solborne_presales_outbox SET sequence=sequence+1 WHERE registration_id=(SELECT registration_id FROM solborne_walk_completions WHERE id=NEW.completion_id); END;
CREATE TRIGGER presales_solborne_owner_reviews_delete AFTER DELETE ON solborne_owner_reviews BEGIN UPDATE solborne_presales_outbox SET sequence=sequence+1 WHERE registration_id=(SELECT registration_id FROM solborne_walk_completions WHERE id=OLD.completion_id); END;
CREATE TRIGGER presales_solborne_website_releases_insert AFTER INSERT ON solborne_website_releases BEGIN UPDATE solborne_presales_outbox SET sequence=sequence+1 WHERE registration_id=(SELECT registration_id FROM solborne_walk_completions WHERE id=NEW.completion_id); END;
CREATE TRIGGER presales_solborne_website_releases_update AFTER UPDATE ON solborne_website_releases BEGIN UPDATE solborne_presales_outbox SET sequence=sequence+1 WHERE registration_id=(SELECT registration_id FROM solborne_walk_completions WHERE id=NEW.completion_id); END;
CREATE TRIGGER presales_solborne_website_releases_delete AFTER DELETE ON solborne_website_releases BEGIN UPDATE solborne_presales_outbox SET sequence=sequence+1 WHERE registration_id=(SELECT registration_id FROM solborne_walk_completions WHERE id=OLD.completion_id); END;
